using System.Drawing;
namespace Downfield {
public partial class GameForm {
 FootballBowling bowlingMatch;bool bowlingTwoPlayers;Franchise bowlingClub;int bowlingSeed;float bowlingPlayTime;bool bowlingThrew;string quickTeamBack="exhibition";
 bool BowlingCpuTurn {get{return bowlingMatch!=null&&!bowlingMatch.TwoPlayers&&bowlingMatch.Turn==1;}}
 string[] BowlingRows(){if(screen=="bowlsetup")return new string[]{"TEAM 1","TEAM 2",bowlingTwoPlayers?"2 PLAYERS / TAKE TURNS":"VS CPU","WEATHER "+new string[]{"AUTO","CLEAR","RAIN","SNOW"}[quickWeather],"START BOWLING","BACK"};return new string[]{bowlingMatch!=null&&bowlingMatch.Complete?"PLAY AGAIN":"NEXT PLAY","RULES","MAIN MENU"};}
 void ActivateBowlingMenu(){if(screen=="bowlsetup"){if(selection<2){quickChoosing=selection;quickTeamBack="bowlsetup";Open("quickteam");}else if(selection==2)bowlingTwoPlayers=!bowlingTwoPlayers;else if(selection==3)quickWeather=(quickWeather+1)%4;else if(selection==4)StartBowling();else Open("home");return;}if(screen=="bowlrules"){if(bowlingMatch!=null&&!bowlingMatch.Complete)BeginBowlingRoll();else Open(bowlingMatch==null?"bowlsetup":"bowlcard");return;}if(selection==0){if(bowlingMatch.Complete)StartBowling();else BeginBowlingRoll();}else if(selection==1)Open("bowlrules");else{bowlingMatch=null;Open("home");}}
 void StartBowling(){StartExhibition(false);bowlingClub=game.Franchise;bowlingSeed=Environment.TickCount;bowlingMatch=new FootballBowling{Teams=new int[]{quickHome,quickAway},TwoPlayers=bowlingTwoPlayers};Open("bowlrules");}
 void BeginBowlingRoll(){int side=bowlingMatch.Turn;bowlingClub.UserTeam=bowlingMatch.Teams[side];game=new Simulation(unchecked(bowlingSeed+bowlingMatch.RollCount*113));game.Exhibition=true;game.Difficulty=difficulty;game.WeatherSelection=quickWeather;bowlingClub.Apply(game,bowlingMatch.Teams[1-side]);game.Postseason=game.Championship=false;game.BowlName="DOWNFIELD BOWLING";game.NewGame();game.StartBowlingRoll(bowlingMatch.Current.PinsLeft);game.MatchIntroTime=0;bowlingPlayTime=0;bowlingThrew=false;if(BowlingCpuTurn){int[] plays={0,6,14,15,22,10,18,29,34,24};game.CallPlay(plays[(bowlingMatch.RollCount+bowlingMatch.Current.Frame)%plays.Length]);}screen="game";selection=0;cameraZ=game.Spot-7;cameraX=0;pendingThrow=0;stickReady=true;input.Clear();}
 bool TickBowling(){if(bowlingMatch==null||!game.Bowling)return false;if(game.BowlingRollFinished&&!game.AmbulanceActive){bowlingMatch.Record(game.BowlingPins);Open("bowlcard");return true;}if(BowlingCpuTurn&&game.State==Phase.PreSnap){if(game.EmergencyChoicePending){List<ClubPlayer> list=game.EmergencyCandidates();if(list.Count>0)game.ChooseEmergencyQB(list[0].Id);}game.Snap();}return false;}
 void BowlingMovement(float dt,ref float x,ref float z){if(!BowlingCpuTurn||!game.Bowling)return;x=z=0;bowlingPlayTime+=dt;if(game.State!=Phase.Live)return;game.Sprint=true;if(game.CanThrow&&!bowlingThrew){if(game.Pressure>.7f)x=game.Controlled.X>0?1:-1;if(bowlingPlayTime>.85f){int receiver=BestBowlingReceiver();game.BeginPass(receiver);game.Charge=.3f;game.ReleasePass();bowlingThrew=true;}}else if(!game.HandoffPending){z=1;float nearest=100;Player close=null;foreach(Player d in game.Players)if(d.Team==1&&d.Active){float distance=Simulation.Distance(game.Controlled.X,game.Controlled.Z,d.X,d.Z);if(distance<nearest){nearest=distance;close=d;}}if(close!=null&&nearest<4){x=game.Controlled.X>close.X?.5f:-.5f;if(nearest<1.8f&&game.Controlled.Z>game.Spot)game.SkillMove(x,1);}if(game.RunPlay){float[] lane=game.RunPoint(bowlingPlayTime);x=Math.Max(-.8f,Math.Min(.8f,(lane[0]-game.Controlled.X)*.2f));}}}
 int BestBowlingReceiver(){int best=0;float value=-999;for(int i=0;i<5;i++){Player p=game.Receiver(i);if(!p.Active||p==game.Controlled)continue;float gap=30;foreach(Player d in game.Players)if(d.Team==1&&d.Active)gap=Math.Min(gap,Simulation.Distance(p.X,p.Z,d.X,d.Z));float score=gap+Math.Min(10,p.Z-game.Spot)*.16f-(p.Z>108?10:0);if(score>value){value=score;best=i;}}return best;}
 void DrawBowlingMenu(){Rect(0,0,1280,800,Ink);TextAt("FOOTBALL BOWLING",40,35,36,Gold);if(screen=="bowlrules"){TextAt("10 YARDS. 2 PLAYS. 10 FRAMES.",70,155,25,White);string[] rules={"TOUCHDOWN ON PLAY 1: STRIKE / X","TOUCHDOWN ON PLAY 2: SPARE / /","EVERY YARD GAINED IS ONE PIN.","PLAY 2 STARTS WHERE PLAY 1 FINISHED.","STRIKE: 10 + NEXT TWO PLAYS' PINS.","SPARE: 10 + NEXT PLAY'S PINS.","FRAME 10: BONUS PLAYS FOR A STRIKE OR SPARE.","NO KICKS. NO CLOCK. PERFECT SCORE: 300."};for(int n=0;n<rules.Length;n++)TextAt(rules[n],70,230+n*49,14,n==7?Gold:Mint);Tile("LET'S PLAY",7,40,690,1200,55,0);return;}if(screen=="bowlsetup"){TextAt("START AT THE 10 / TWO SHOTS TO SCORE",40,100,14,Mint);string[] rows=BowlingRows();for(int n=0;n<rows.Length;n++){float x=40+n%2*610,y=155+n/2*188;Tile(rows[n],n,x,y,590,163,n);if(n<2){DrawTeamLogo(franchise.Teams[n==0?quickHome:quickAway],x+26,y+20,58);TextAt(franchise.Teams[n==0?quickHome:quickAway].Name,x+24,y+107,12,Gold);}}return;}
  FootballBowling match=bowlingMatch;if(match==null){Open("bowlsetup");return;}for(int side=0;side<2;side++){LeagueTeam team=franchise.Teams[match.Teams[side]];float y=130+side*205;DrawTeamLogo(team,40,y,55);TextAt(team.Name,115,y+5,18,White);TextAt((match.TwoPlayers?"PLAYER "+(side+1):side==0?"YOU":"CPU")+" / "+match.Cards[side].Score+" PTS",820,y+5,18,side==match.Turn?Gold:Muted);DrawBowlingCard(match.Cards[side],y+57,side==match.Turn&&!match.Complete);}
  TextAt(match.LastResult,40,563,28,Gold);string next;if(match.Complete){int a=match.Cards[0].Score,b=match.Cards[1].Score;next=a==b?"TIE GAME":franchise.Teams[match.Teams[a>b?0:1]].Mascot+" WINS";}else next=(match.TwoPlayers?"PASS CONTROLLER TO PLAYER "+(match.Turn+1):match.Turn==0?"YOUR TURN":"CPU TURN")+" / FRAME "+(match.Current.Frame+1);TextAt(next,40,614,18,Mint);string[] choices=BowlingRows();for(int n=0;n<3;n++)Tile(choices[n],n,40+n*407,690,390,55,n);}
 void DrawBowlingCard(BowlingCard card,float y,bool active){int?[] scores=card.Cumulative();for(int n=0;n<10;n++){float x=40+n*120;Rect(x,y,116,102,active&&card.Frame==n?Color.FromArgb(66,91,96):Color.FromArgb(34,43,57));TextAt((n+1).ToString(),x+9,y+8,10,Muted);TextAt(card.Marks(n),x+8,y+33,12,Gold);Line(x+4,y+61,x+112,y+61,Muted,1);TextAt(scores[n].HasValue?scores[n].Value.ToString():card.Frames[n].Rolls.Count>0?"...":"",x+8,y+76,14,White);}}
 void DrawBowlingHUD(){if(!game.Bowling||bowlingMatch==null)return;Rect(0,0,1280,105,Ink);Rect(0,100,1280,5,Gold);TextAt("BOWLING / FRAME "+(bowlingMatch.Current.Frame+1),24,17,18,Gold);TextAt(franchise.Teams[bowlingMatch.Teams[0]].Mascot+" "+bowlingMatch.Cards[0].Score+"  -  "+bowlingMatch.Cards[1].Score+" "+franchise.Teams[bowlingMatch.Teams[1]].Mascot,24,59,18,White);TextAt("PLAY "+(bowlingMatch.Current.Frames[bowlingMatch.Current.Frame].Rolls.Count+1),795,18,18,Mint);TextAt(bowlingMatch.Current.PinsLeft+" YARDS TO GO",795,60,18,White);if(BowlingCpuTurn){Rect(390,120,500,36,Ink);TextAt("CPU OFFENSE / WATCH THIS TURN",410,131,12,Gold);}if(game.State==Phase.PreSnap){Rect(0,733,1280,30,Ink);TextAt("TWO PLAYS TO SCORE / NO KICKS / EVERY YARD IS A PIN",24,739,11,Muted);}}
}
